function iniciarSPA(){console.log("SPA iniciada!")}function validarFormulario(){console.log("Validação iniciada!");const e=document.querySelector(".form-cadastro");e?e.addEventListener("submit",o=>{o.preventDefault();const r=e.querySelectorAll("input[required], textarea[required]");let a=!0;r.forEach(e=>{e.classList.remove("error"),e.value.trim()||(e.classList.add("error"),a=!1)}),a?(alert("✅ Cadastro enviado com sucesso!"),e.reset()):alert("⚠️ Preencha todos os campos obrigatórios!")}):console.warn("⚠️ Nenhum formulário encontrado!")}document.addEventListener("DOMContentLoaded",()=>{iniciarSPA(),validarFormulario()});